const input = $input.first().json;
const originalData = $('Normaliser — Input').first().json;

let enhancedPrompt = originalData.prompt;

try {
  // The native Gemini node returns content in different formats
  let text = '';
  if (typeof input === 'string') {
    text = input;
  } else if (input.content) {
    // Native node format: { content: { parts: [{ text: '...' }] } }
    const parts = input.content?.parts || [];
    text = parts.map(p => p.text || '').join('');
  } else if (input.text) {
    text = input.text;
  } else if (input.output) {
    text = input.output;
  } else {
    // Try to find text in the raw response
    text = JSON.stringify(input);
  }

  if (text) {
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      if (parsed.enhanced_prompt) {
        enhancedPrompt = parsed.enhanced_prompt;
      }
    }
  }
} catch (e) {
  // Fallback to original
}

if (!enhancedPrompt || enhancedPrompt.trim() === '') {
  enhancedPrompt = originalData.prompt;
}

return [{
  json: {
    prompt: enhancedPrompt,
    original_prompt: originalData.prompt,
    type: originalData.type,
    dimensions: originalData.dimensions,
    context: originalData.context,
    for_workflow: originalData.for_workflow
  }
}];

const input = $input.first();
const promptData = $('Parse — Prompt enrichi').first().json;
const now = new Date().toISOString();
const timestamp = now.replace(/[:.]/g, '-').substring(0, 19);

// Determine R2 prefix based on type
const typeMap = {
  article: 'articles',
  formation: 'formations',
  social_post: 'social/posts',
  carousel: 'social/carousels',
  reel: 'social/reels',
  lesson: 'lessons',
  newsletter: 'newsletter',
  course_cover: 'formations'
};
const prefix = typeMap[promptData.type] || 'misc';

// Build slug from context
const slug = (promptData.slug || promptData.type || 'media')
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '')
  .substring(0, 60);

const filename = slug + '-' + timestamp + '.png';
const r2_key = prefix + '/' + filename;

const result = {
  json: {
    filename,
    r2_key,
    r2_bucket: 'maxmorrys-lms',
    type: promptData.type,
    dimensions: promptData.dimensions,
    original_prompt: promptData.original_prompt,
    enhanced_prompt: promptData.prompt,
    for_workflow: promptData.for_workflow,
    context: promptData.context,
    slug: promptData.slug || slug,
    generated_at: now
  }
};

if (input.binary) {
  result.binary = input.binary;
}

return [result];

